import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Vendor audit trail", () => {
  test(
    "Audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange: signed in as member@northwind.test
      const member = await apiAs("member");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("AUD-01 Vendor"),
          category: "services",
          contact_email: `aud01.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% AUD-01 synthetic W-9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Extraction may run asynchronously; wait until the document reaches extracted.
      let status = document.status as string;
      const deadline = Date.now() + 60_000;
      while (status !== "extracted" && status !== "failed" && Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        const docResponse = await member.get(`/api/documents/${document.id}`);
        expect(docResponse.status()).toBe(200);
        status = (await docResponse.json()).status;
      }
      expect(status).toBe("extracted");

      // Act
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);

      // Assert
      expect(auditResponse.status()).toBe(200);
      const trail = (await auditResponse.json()) as {
        items: Array<{
          id: number;
          action: string;
          actor: { id: string; name: string; email: string };
          at: string;
        }>;
      };

      expect(trail.items.map((event) => event.action)).toEqual([
        "vendor.created",
        "document.uploaded",
        "document.extracted",
      ]);

      for (const event of trail.items) {
        expect(event.actor.name).toBeTruthy();
        expect(event.actor.email).toBeTruthy();
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      const timestamps = trail.items.map((event) => Date.parse(event.at));
      for (let i = 1; i < timestamps.length; i++) {
        expect(timestamps[i]).toBeGreaterThanOrEqual(timestamps[i - 1]);
      }
    },
  );
});
